INSERT INTO public.questions (question_text,option_a,option_b,option_c,option_d,correct_answer,explanation,tip,difficulty,source,is_verified,category_id)
SELECT v.qt,v.a,v.b,v.c,v.d,v.ca,v.ex,v.tp,v.df::public.difficulty_level,'AUTHORED',true,c.id
FROM (VALUES
('Um sinal triangular com a figura de duas crianças indica:','Escola de condução','Proximidade de zona frequentada por crianças','Parque infantil proibido','Passagem de peões obrigatória','B','Trata-se de um sinal de perigo que avisa da presença provável de crianças, exigindo velocidade muito reduzida.','Crianças no sinal: pé no travão.','facil','sinais-de-transito'),
('Um sinal triangular com um símbolo de queda de pedras avisa:','Obras na via','Risco de derrocada ou pedras na faixa de rodagem','Zona de escavação','Terreno agrícola','B','O condutor deve reduzir a velocidade e estar atento a obstáculos inesperados na via.','Encosta na estrada: olhos no piso.','medio','sinais-de-transito'),
('Um sinal circular vermelho com um camião a preto significa:','Estacionamento de pesados','Trânsito proibido a veículos pesados de mercadorias','Zona de cargas e descargas','Paragem de pesados','B','É um sinal de proibição dirigido a uma categoria específica de veículos.','Círculo vermelho: proibição.','medio','sinais-de-transito'),
('Um sinal com fundo amarelo e forma de losango indica:','Fim de via prioritária','Via com prioridade','Zona escolar','Proibição temporária','B','O losango amarelo indica que se circula numa via com prioridade em relação às vias que a cruzam.','Losango amarelo: você tem prioridade.','dificil','sinais-de-transito'),
('As setas pintadas no pavimento antes de um cruzamento servem para:','Decoração','Indicar as direções permitidas em cada via de trânsito','Marcar estacionamento','Indicar a velocidade','B','O condutor deve posicionar-se atempadamente na via correspondente à direção que pretende tomar.','Escolha a via cedo, não em cima do cruzamento.','facil','sinais-de-transito'),
('Uma linha branca contínua junto ao lancil indica normalmente:','Zona de paragem autorizada','Proibição de parar e estacionar','Faixa para bicicletas','Início de passadeira','B','As marcas junto ao limite da faixa restringem a imobilização de veículos.','Risco junto ao passeio: não pare ali.','medio','sinais-de-transito'),
('O sinal luminoso verde intermitente indica:','Que o verde vai terminar em breve','Avaria do semáforo','Passagem obrigatória','Prioridade absoluta','A','O verde intermitente avisa que a fase de verde está a terminar e prepara o condutor para parar.','Verde a piscar: prepare-se para parar.','medio','sinais-de-transito'),
('Um sinal com uma seta branca sobre fundo azul redondo indica:','Sentido proibido','Sentido obrigatório','Via de sentido único','Via reservada','B','Os sinais azuis redondos com setas impõem o sentido a seguir.','Seta azul manda seguir.','facil','sinais-de-transito'),
('Ao aproximar-se de um cruzamento com o semáforo verde, o condutor deve:','Passar sem olhar','Verificar se o cruzamento está livre antes de avançar','Acelerar','Buzinar','B','O verde autoriza mas não garante segurança; pode haver veículos ou peões ainda no cruzamento.','Verde é permissão, não garantia.','facil','regras-de-transito'),
('Circular com um farol fundido:','Não tem importância','Reduz a visibilidade e a perceção da largura do veículo pelos outros','Só é problema de dia','É permitido em vias iluminadas','B','Um só farol dificulta a perceção do tipo e largura do veículo, sobretudo à noite.','Uma luz só parece uma mota.','medio','regras-de-transito'),
('Transportar carga que ultrapassa a largura do veículo:','É livre','Exige sinalização adequada e cuidados especiais','É proibido sempre','Só é permitido de noite','B','A carga deve estar bem acondicionada e devidamente sinalizada para não constituir perigo.','Carga mal presa é carga perigosa.','medio','regras-de-transito'),
('A utilização das luzes de perigo (quatro piscas) é adequada:','Para estacionar em segunda fila','Quando o veículo constitui um perigo para os restantes utentes','Para agradecer','Em toda a condução com chuva','B','As luzes de perigo assinalam imobilização forçada ou risco súbito, como fila parada em autoestrada.','Quatro piscas avisam perigo, não desculpam infrações.','medio','regras-de-transito'),
('Numa via com três filas de trânsito no mesmo sentido, a fila da direita destina-se sobretudo a:','Ultrapassagens','Circulação normal, incluindo veículos mais lentos','Veículos de emergência','Paragens','B','A regra de ocupar a direita mantém a fluidez e liberta as filas da esquerda para ultrapassagens.','Circular à direita é regra, não castigo.','medio','regras-de-transito'),
('Um condutor que pretende mudar de fila deve:','Mudar rapidamente sem sinalizar','Sinalizar, verificar espelhos e ângulo morto e mudar sem forçar','Buzinar','Travar antes de mudar','B','A mudança de fila só é segura quando não obriga outro condutor a travar ou desviar-se.','Mudar de fila não é abrir caminho à força.','facil','regras-de-transito'),
('Numa intersecção regulada por agente, quando este mantém o braço levantado verticalmente:','Todos devem parar, salvo quem já não o possa fazer em segurança','Todos podem avançar','Só os veículos pesados param','Só os peões param','A','O braço levantado equivale ao sinal amarelo, ordenando a paragem.','Braço no ar: pare.','dificil','sinais-de-transito'),
('Um veículo que sai de uma rotunda pela terceira saída deve, ao circular na rotunda:','Manter-se sempre na via exterior','Posicionar-se conforme a sinalização e sinalizar a saída à direita','Circular pelo centro','Parar antes de cada saída','B','O posicionamento depende da sinalização; a sinalização de saída é sempre obrigatória.','Sinalize a saída, sempre.','medio','prioridade'),
('Se dois veículos se aproximam de um cruzamento e um deles pretende virar à esquerda:','Vira primeiro quem quer virar à esquerda','Deve ceder passagem ao veículo que segue em sentido contrário','Passa o veículo maior','Passa quem chegar primeiro','B','Quem vira à esquerda atravessa a trajetória do trânsito em sentido contrário e deve esperar.','Virar à esquerda: espere o corredor livre.','medio','prioridade'),
('Perante uma ambulância com sirene parada num engarrafamento, o condutor deve:','Ignorar','Procurar criar corredor de emergência sem infringir a segurança','Sair pela berma sempre','Buzinar','B','Facilitar o corredor de emergência pode salvar vidas, com manobras prudentes.','Abra caminho com calma.','medio','prioridade'),
('Numa via onde existe o sinal de cedência de passagem, o condutor:','Deve parar sempre','Deve reduzir e parar apenas se necessário para ceder passagem','Tem prioridade','Deve buzinar','B','Ao contrário do STOP, a cedência não obriga à paragem se a via estiver livre.','Cedência: parar só se preciso.','medio','prioridade'),
('Um veículo que circula sobre carris (comboio ou elétrico):','Cede sempre passagem','Tem prioridade por não poder desviar-se','Cede aos ligeiros','Não tem regras','B','Os veículos sobre carris não podem mudar de trajetória, pelo que têm prioridade.','Quem não pode desviar-se, passa primeiro.','facil','prioridade'),
('É proibido ultrapassar imediatamente antes e sobre:','Uma ponte larga','Uma passagem de nível','Uma reta','Uma zona urbana','B','Nas passagens de nível a ultrapassagem é proibida por causa do espaço reduzido e do risco.','Passagem de nível: nunca ultrapassar.','medio','ultrapassagem'),
('Ao ultrapassar um veículo pesado, o condutor deve considerar:','Que a manobra é rápida','Que precisa de mais espaço e tempo do que aparenta','Que o pesado vai travar','Que pode usar a berma','B','O comprimento do pesado e a diferença de velocidade tornam a manobra longa e exigente.','Ultrapassar camião pede reta longa.','medio','ultrapassagem'),
('Se durante uma ultrapassagem surgir um veículo em sentido contrário:','Deve acelerar sempre','Deve avaliar e, se necessário, abortar a manobra regressando à direita','Deve travar no meio da via','Deve buzinar','B','A decisão deve ser tomada cedo; regressar em segurança é preferível a completar a manobra à força.','Na dúvida, aborte a ultrapassagem.','dificil','ultrapassagem'),
('Ultrapassar pela direita é admissível:','Nunca','Quando o condutor da frente sinalizou que vai virar à esquerda e a manobra é segura','Sempre em autoestrada','Em rotundas','B','Trata-se de uma exceção prevista, exigindo espaço suficiente e segurança.','Só pela direita em casos previstos.','dificil','ultrapassagem'),
('Depois de concluir a ultrapassagem, o condutor deve:','Manter-se na esquerda','Regressar à direita logo que possa fazê-lo sem perigo','Reduzir bruscamente','Ligar os quatro piscas','B','A permanência desnecessária na esquerda obstrui o trânsito e é infração.','Passou? Volte à direita.','facil','ultrapassagem'),
('Estacionar num cruzamento ou nas suas proximidades:','É permitido de dia','É proibido por reduzir a visibilidade','É permitido em vias largas','Depende da hora','B','Um veículo estacionado junto ao cruzamento esconde peões e veículos que se aproximam.','Cruzamento tem de ficar limpo.','facil','paragem-estacionamento'),
('Estacionar em frente a um hidrante ou saída de emergência:','É permitido brevemente','É proibido por impedir socorro em emergência','É permitido com aviso','Só é proibido em hospitais','B','O bloqueio de meios de socorro pode custar vidas.','Não estacione onde os bombeiros precisam.','facil','paragem-estacionamento'),
('Ao sair do veículo estacionado na via, o condutor deve:','Abrir a porta rapidamente','Verificar o trânsito antes de abrir a porta','Sair pelo lado da via sempre','Deixar a porta aberta','B','Abrir a porta sem verificar é causa frequente de acidentes com ciclistas e motociclistas.','Olhe pelo espelho antes de abrir a porta.','facil','paragem-estacionamento'),
('Estacionar contra o sentido do trânsito numa via de dois sentidos:','É permitido à noite','É proibido, salvo indicação em contrário','É permitido em vias largas','É recomendado','B','A regra é estacionar no sentido da marcha, junto à berma direita.','Estacione no sentido em que conduzia.','medio','paragem-estacionamento'),
('Deixar o motor a trabalhar com o veículo estacionado e sem vigilância:','É aconselhável no inverno','Deve ser evitado por razões de segurança e ambientais','É obrigatório para carregar a bateria','Não tem qualquer implicação','B','Um veículo com motor a trabalhar sem condutor é um risco de furto e de acidente.','Saiu do carro? Desligue o motor.','medio','paragem-estacionamento'),
('Perante um sinal de velocidade máxima de 40 km/h numa zona escolar:','Pode circular a 60 km/h se não houver crianças','Deve respeitar o limite de 40 km/h','Pode ignorar fora do horário escolar','Pode circular a 50 km/h','B','A sinalização específica prevalece sobre o limite geral, independentemente da hora.','Sinal específico manda mais que a regra geral.','facil','velocidade'),
('Ao descer uma encosta longa, para controlar a velocidade deve:','Circular em ponto morto','Usar o travão motor engrenando uma velocidade adequada','Usar apenas o travão de pé','Desligar o motor','B','O uso contínuo dos travões provoca sobreaquecimento e perda de eficácia.','Descida longa: engrene e deixe o motor travar.','dificil','velocidade'),
('A velocidade excessiva reduz sobretudo:','O consumo','O tempo disponível para reagir e o campo visual','O ruído','O desgaste dos pneus','B','A altas velocidades a visão periférica estreita-se e a informação chega mais depressa do que a capacidade de reagir.','Quanto mais rápido, menos se vê.','medio','velocidade'),
('Em piso de terra batida ou gravilha, o condutor deve:','Manter a velocidade da estrada asfaltada','Reduzir a velocidade devido à menor aderência','Travar bruscamente nas curvas','Circular pelo centro sempre','B','A aderência em pisos soltos é muito inferior e a travagem é imprevisível.','Gravilha: devagar e sem manobras bruscas.','facil','velocidade'),
('Numa fila a alta velocidade, a distância de segurança deve ser:','Menor para evitar entradas de outros veículos','Maior, proporcional à velocidade','Fixa em 5 metros','Irrelevante','B','A distância deve crescer com a velocidade porque o espaço de paragem aumenta.','Mais velocidade, mais espaço.','facil','distancia-seguranca'),
('O tempo de reação médio de um condutor atento é aproximadamente:','0,1 segundos','1 segundo','5 segundos','10 segundos','B','Cerca de um segundo é o valor de referência, aumentando com fadiga, álcool ou distração.','A 100 km/h, 1 segundo são 28 metros.','medio','distancia-seguranca'),
('Ser pressionado por um condutor que segue demasiado perto exige:','Travar para o afastar','Manter velocidade constante e, se possível, facilitar a ultrapassagem','Acelerar acima do limite','Ligar os quatro piscas','B','Travar para castigar quem segue perto pode provocar colisão traseira grave.','Deixe passar o apressado.','medio','distancia-seguranca'),
('Ao ser ultrapassado e ver o veículo a entrar à frente, o condutor deve:','Acelerar','Aliviar o acelerador para restabelecer a distância de segurança','Buzinar','Colar-se ao veículo','B','Restabelecer o espaço protege ambos os veículos.','Recupere a distância, não o orgulho.','facil','distancia-seguranca'),
('Manter o olhar longe, na estrada à frente, permite:','Ver mais cedo os perigos e planear','Poupar combustível','Reduzir o consumo de pneus','Evitar multas','A','Olhar longe dá tempo para antecipar travagens, obstáculos e mudanças de trânsito.','Olhos longe, mãos calmas.','facil','conducao-defensiva'),
('Ao aproximar-se de um cruzamento onde a visibilidade é reduzida:','Deve manter a velocidade','Deve reduzir e aproximar-se de forma a poder parar','Deve acelerar para reduzir a exposição','Deve buzinar e avançar','B','Só é possível decidir com segurança quando existe visibilidade suficiente.','Se não vê, não avance.','facil','conducao-defensiva'),
('A técnica de olhar pelos espelhos deve ser:','Feita apenas antes de travar','Frequente e sistemática durante toda a condução','Feita apenas em autoestrada','Desnecessária com câmaras','B','A consciência do que está atrás e ao lado é essencial para qualquer manobra.','Espelhos a cada poucos segundos.','facil','conducao-defensiva'),
('Perante um obstáculo súbito na via, a reação mais segura é normalmente:','Desviar bruscamente','Travar firmemente mantendo o controlo da direção','Acelerar','Fechar os olhos','B','A travagem em linha reta mantém a estabilidade; desvios bruscos causam despistes.','Trave reto, depois desvie se der.','medio','conducao-defensiva'),
('Conduzir com atenção dividida entre a estrada e o GPS:','Não tem risco','Aumenta o risco por reduzir a atenção visual e mental','Melhora o planeamento','Só é perigoso à noite','B','Qualquer tarefa secundária retira recursos de atenção à condução.','Configure o GPS antes de arrancar.','facil','conducao-defensiva'),
('O álcool afeta primeiro:','A força muscular','O juízo crítico e a capacidade de avaliar riscos','A visão apenas','A audição apenas','B','A autocrítica é das primeiras funções afetadas, o que leva a condutores confiantes mas incapazes.','O álcool tira o travão da prudência.','medio','alcool'),
('Um condutor pode ser fiscalizado quanto à alcoolemia:','Só depois de um acidente','Em qualquer operação de fiscalização','Só à noite','Só em autoestrada','B','As autoridades podem realizar testes em ações de fiscalização de rotina.','A fiscalização pode ser a qualquer hora.','facil','alcool'),
('O álcool afeta a visão sobretudo por:','Aumentar o campo visual','Reduzir a visão periférica e a adaptação à luz','Melhorar a visão noturna','Não afetar a visão','B','Sob efeito do álcool, o campo visual estreita-se e a recuperação ao encandeamento é mais lenta.','Álcool cria visão em túnel.','medio','alcool'),
('Depois de uma noite de consumo elevado de álcool, na manhã seguinte:','Está sempre apto a conduzir','Pode ainda apresentar taxa de álcool no sangue','O álcool desapareceu com o sono','Basta comer para eliminar','B','A eliminação é lenta, cerca de uma pequena fração por hora, podendo persistir de manhã.','O álcool não dorme quando você dorme.','medio','alcool'),
('A melhor forma de evitar conduzir alcoolizado é:','Beber devagar','Planear o regresso com condutor designado ou transporte alternativo','Beber apenas cerveja','Comer bem antes','B','A decisão deve ser tomada antes de começar a beber.','Decida o regresso antes do primeiro copo.','facil','alcool'),
('Uma sesta eficaz para combater a fadiga deve durar aproximadamente:','2 horas','15 a 20 minutos','1 minuto','5 horas','B','Uma sesta curta restaura a vigilância sem provocar a inércia do sono profundo.','15 minutos de sesta valem mais que 3 cafés.','medio','fadiga'),
('Bocejar repetidamente e piscar muito os olhos ao volante indica:','Boa disposição','Sinal de fadiga que exige paragem','Falta de combustível','Excesso de luz','B','São sinais precoces de sonolência e devem ser levados a sério.','Bocejo é aviso, não hábito.','facil','fadiga'),
('Conduzir em horários de baixa vigilância, como a madrugada:','É mais seguro por haver pouco trânsito','Aumenta o risco devido ao ritmo biológico','Não tem influência','Melhora a atenção','B','Entre as 2h e as 6h o organismo tem o menor nível de alerta.','Madrugada é o pior horário para conduzir cansado.','medio','fadiga'),
('Refeições muito pesadas antes de conduzir:','Melhoram a atenção','Podem aumentar a sonolência','Não têm efeito','Substituem o descanso','B','A digestão pesada favorece a sonolência pós-prandial.','Coma leve antes de viajar.','facil','fadiga'),
('Um condutor irritado deve, antes de arrancar:','Conduzir para desanuviar','Acalmar-se, pois a emoção intensa prejudica as decisões','Conduzir mais depressa','Ouvir música alta','B','Estados emocionais intensos aumentam a impulsividade e o risco.','Zangado? Espere cinco minutos.','medio','comportamento'),
('Buzinar insistentemente num engarrafamento:','Resolve o trânsito','Aumenta o stress geral sem qualquer benefício','É obrigatório','Avisa a polícia','B','O ruído acrescenta tensão e não altera o trânsito.','Buzinar não desimpede a rua.','facil','comportamento'),
('Um condutor experiente e prudente reconhece que:','Nunca comete erros','Todos cometem erros e por isso mantém margens de segurança','Só os outros erram','A experiência elimina o risco','B','A humildade ao volante é um dos principais fatores de segurança.','Errar é humano; prever é seguro.','facil','comportamento'),
('Competir com outro condutor na via:','Demonstra perícia','É comportamento de alto risco e proibido','É aceitável em autoestrada','Depende do veículo','B','As corridas na via pública são infrações graves e causam acidentes mortais.','A estrada não é pista.','facil','comportamento'),
('O cinto de segurança deve passar:','Sobre o pescoço','Sobre o ombro e a bacia, bem ajustado','Debaixo do braço','Sobre o abdómen apenas','B','A posição correta distribui as forças pelas zonas ósseas mais resistentes.','Cinto no ombro e na anca, nunca no pescoço.','facil','seguranca-rodoviaria'),
('Uma criança com menos de 12 anos e menos de 1,35 m deve viajar:','No banco da frente','No banco de trás com sistema de retenção adequado','Sem cinto','Ao colo','B','A regra protege a criança da força do airbag e adapta a retenção à sua estatura.','Criança pequena viaja atrás e presa.','facil','seguranca-rodoviaria'),
('O encosto de cabeça e a posição do banco devem permitir:','Braços totalmente esticados','Ligeira flexão dos braços e alcance total dos pedais','Ficar o mais longe possível','Ficar colado ao volante','B','Uma posição correta melhora o controlo e reduz lesões em caso de colisão.','Braços ligeiramente dobrados no volante.','medio','seguranca-rodoviaria'),
('Transportar animais soltos no habitáculo:','É seguro','Pode distrair o condutor e causar lesões em travagens','É obrigatório','Não é permitido em nenhum caso','B','Os animais devem ser transportados com sistemas de retenção próprios.','Animal preso, condutor tranquilo.','medio','seguranca-rodoviaria'),
('Os coletes refletores devem ser usados:','Dentro do veículo','Ao sair do veículo em caso de imobilização na via','Apenas de dia','Apenas por profissionais','B','O colete torna o condutor visível a grande distância, reduzindo o risco de atropelamento.','Vista o colete antes de sair do carro.','facil','seguranca-rodoviaria'),
('Circular com vidros muito escurecidos além do permitido:','Melhora a segurança','Reduz a visibilidade do condutor, sobretudo à noite','É indiferente','É obrigatório em zonas quentes','B','A redução de transmissão luminosa compromete a visão noturna e o contacto visual com peões.','Vidro escuro esconde o perigo.','medio','seguranca-rodoviaria'),
('Ao circular numa via bem iluminada dentro de uma localidade, deve usar:','Máximos','Luzes de cruzamento','Nenhuma luz','Luzes de nevoeiro','B','Dentro das localidades usam-se médios para não encandear outros utentes.','Na cidade, médios.','facil','conducao-noturna'),
('A fadiga visual noturna aumenta quando:','Se usa o para-brisas limpo','O para-brisas está sujo ou riscado, dispersando a luz','Se conduz devagar','Há pouca iluminação pública','B','A sujidade difunde a luz e cria halos, aumentando o esforço visual.','Para-brisas limpo é meia visão ganha.','medio','conducao-noturna'),
('Ao seguir atrás de outro veículo à noite, deve usar:','Máximos','Luzes de cruzamento para não encandear pelo espelho','Nenhuma luz','Quatro piscas','B','Os máximos refletem no espelho do veículo da frente e encandeiam o condutor.','Atrás de alguém: médios.','facil','conducao-noturna'),
('Um peão vestido de escuro à noite:','É facilmente visível','Pode ser detetado muito tarde, exigindo velocidade reduzida','Não circula na via','Tem prioridade absoluta','B','A distância de deteção pode ser inferior à distância de paragem, sobretudo com máximos apagados.','De noite, conduza esperando o invisível.','medio','conducao-noturna'),
('Se os faróis falharem durante a noite, o condutor deve:','Continuar devagar','Sinalizar, reduzir e imobilizar o veículo em local seguro','Usar o telemóvel como lanterna','Acelerar até à localidade','B','Sem iluminação a condução é perigosa e ilegal.','Sem luz, saia da estrada.','medio','conducao-noturna'),
('Poças de água acumuladas numa faixa de rodagem devem ser:','Atravessadas a alta velocidade','Atravessadas com velocidade reduzida e volante firme','Ignoradas','Evitadas com desvios bruscos','B','A entrada rápida numa poça pode provocar perda de direção repentina.','Poça: abrande antes, não em cima.','medio','aquaplanagem'),
('Uma sensação súbita de leveza no volante com chuva indica:','Direção assistida a falhar','Possível início de aquaplanagem','Pneu furado','Excesso de carga','B','A perda de contacto com o piso elimina o retorno de esforço na direção.','Volante leve na chuva: alivie o pé.','dificil','aquaplanagem'),
('Para reduzir o risco de aquaplanagem, o condutor deve:','Aumentar a velocidade em zonas alagadas','Reduzir a velocidade e manter os pneus em bom estado','Esvaziar os pneus','Travar com frequência','B','Velocidade moderada e pneus com sulcos suficientes permitem escoar a água.','Pneu bom, pé leve, chuva vencida.','facil','aquaplanagem'),
('Em rodados duplos ou pneus largos, o risco de aquaplanagem:','Não existe','Existe igualmente e depende sobretudo do piso e da velocidade','É sempre maior','É sempre menor','B','Nenhum pneu está imune; a velocidade e a altura da lâmina de água são determinantes.','Nenhum pneu flutua bem.','dificil','aquaplanagem'),
('Com nevoeiro, a utilização dos máximos:','Melhora a visibilidade','Piora a visibilidade por reflexão da luz nas gotículas','É obrigatória','Não tem efeito','B','A luz reflete-se nas partículas de água criando uma parede branca.','Nevoeiro: nunca máximos.','facil','meteorologia'),
('Após uma chuvada intensa, a estrada pode apresentar:','Melhor aderência','Lama, areia e detritos arrastados para a faixa de rodagem','Menos trânsito garantido','Piso sempre seco','B','Os detritos reduzem a aderência de forma imprevisível, sobretudo em curvas.','Depois da chuva, cuidado com a lama.','medio','meteorologia'),
('Com calor extremo e asfalto muito quente, os pneus:','Não sofrem alterações','Podem sofrer aumento de pressão e maior desgaste','Ficam mais duros','Perdem cor','B','A temperatura eleva a pressão interna, sendo importante verificar o estado dos pneus.','Calor extremo exige pneus vigiados.','medio','meteorologia'),
('Ao circular com chuva forte, o uso dos limpa para-brisas deve:','Ser evitado','Ser acompanhado de redução de velocidade e luzes acesas','Substituir a redução de velocidade','Só ocorrer de noite','B','A visibilidade reduzida exige menor velocidade e maior visibilidade do próprio veículo.','Chuva: limpa-vidros, luzes e pé leve.','facil','meteorologia'),
('Um ciclista pode ocupar a faixa de rodagem:','Nunca','Sim, respeitando as regras aplicáveis aos veículos','Só em vias urbanas','Apenas de dia','B','O velocípede é um veículo e o ciclista é um condutor com direitos e deveres.','Bicicleta é veículo, não obstáculo.','medio','peoes-velocipedes'),
('Ao virar à direita num cruzamento, o condutor deve verificar:','Apenas o trânsito da frente','A presença de ciclistas e peões pelo lado direito','Somente o espelho central','O trânsito atrás apenas','B','Ciclistas que seguem em frente pela direita são frequentemente atropelados nesta manobra.','Antes de virar à direita, olhe à direita.','medio','peoes-velocipedes'),
('Peões que caminham em grupo fora das localidades e à noite devem:','Andar dispersos','Ser visíveis, usando material refletor sempre que possível','Andar no meio da via','Circular sem luzes','B','A visibilidade é o principal fator de proteção dos peões em vias sem iluminação.','Refletor à noite salva peões.','facil','peoes-velocipedes'),
('Perante um peão com bengala branca:','Deve buzinar','Deve parar e permitir a travessia com total segurança','Deve passar rapidamente','Deve acender os máximos','B','A bengala branca sinaliza uma pessoa com deficiência visual, utente especialmente vulnerável.','Bengala branca: pare sempre.','facil','peoes-velocipedes'),
('O ângulo morto dos camiões é:','Inexistente','Muito extenso, sobretudo do lado direito e à frente','Apenas atrás','Igual ao dos ligeiros','B','Os pontos cegos dos pesados são amplos, colocando em risco quem circula ao seu lado.','Nunca fique ao lado direito de um camião.','medio','veiculos-pesados'),
('Ao ultrapassar um pesado em dia de chuva:','Não há cuidados adicionais','Deve contar com projeção de água e perda momentânea de visibilidade','Deve reduzir a meio da manobra','Deve usar a berma','B','O spray levantado pelos rodados pode cegar temporariamente o condutor.','Ultrapassar camião na chuva: rápido e decidido, ou nada.','medio','veiculos-pesados'),
('Um veículo pesado em subida lenta deve ser ultrapassado:','Sem verificar visibilidade','Apenas com visibilidade e espaço suficientes, dada a sua extensão','Sempre pela direita','Com aviso sonoro obrigatório','B','A diferença de velocidade não dispensa a avaliação do espaço necessário.','Espaço primeiro, manobra depois.','facil','veiculos-pesados'),
('O número nacional de emergência deve ser usado para:','Perguntar direções','Comunicar acidentes com feridos e pedir socorro','Reclamar do trânsito','Reportar buracos','B','As linhas de emergência destinam-se a situações que exigem socorro imediato.','Emergência é para salvar vidas.','facil','acidentes-emergencia'),
('Numa hemorragia abundante, enquanto aguarda socorro deve:','Aplicar água','Fazer compressão direta sobre a ferida','Dar de beber ao ferido','Aplicar gelo diretamente','B','A compressão direta reduz a perda de sangue até à chegada dos meios de socorro.','Pressione e não largue.','dificil','acidentes-emergencia'),
('Dar de beber a um ferido inconsciente:','É recomendado','É perigoso por risco de asfixia','Ajuda a reanimar','É obrigatório','B','O líquido pode entrar nas vias respiratórias de quem não tem reflexos de deglutição.','Ferido inconsciente não bebe nada.','medio','acidentes-emergencia'),
('Se houver risco de incêndio no veículo acidentado:','Deve manter os ocupantes dentro','Deve afastar as pessoas do veículo para local seguro','Deve abrir o capô imediatamente','Deve ligar o motor','B','A prioridade é afastar as pessoas da fonte de risco.','Fogo: afaste primeiro, veja depois.','medio','acidentes-emergencia'),
('Depois de um acidente sem feridos, os condutores devem:','Sair do local sem falar','Preencher a declaração amigável e libertar a via se possível','Discutir na via','Chamar sempre os bombeiros','B','A declaração amigável agiliza o processo e desimpedir a via evita novos acidentes.','Sem feridos: declaração e via livre.','facil','acidentes-emergencia'),
('Um som metálico ao travar pode indicar:','Pneus novos','Pastilhas de travão gastas','Excesso de óleo','Bateria fraca','B','O ruído é frequentemente o indicador de desgaste das pastilhas.','Chiar ao travar: oficina já.','medio','mecanica'),
('O nível de óleo do motor deve ser verificado:','Com o motor quente e em movimento','Com o veículo em plano e o motor frio ou desligado há alguns minutos','Uma vez por ano','Somente pela oficina','B','A leitura correta exige que o óleo tenha escorrido para o cárter e o veículo esteja nivelado.','Verifique o óleo em piso plano.','medio','mecanica'),
('Uma bateria descarregada pode provocar:','Falha no arranque do motor','Aumento da potência','Melhor consumo','Travagem mais eficaz','A','A bateria alimenta o motor de arranque e os sistemas elétricos.','Luzes fracas avisam bateria fraca.','facil','mecanica'),
('Escovas dos limpa para-brisas gastas:','Melhoram a limpeza','Deixam riscos e reduzem a visibilidade com chuva','Não afetam a condução','Só importam de noite','B','A limpeza deficiente compromete a visibilidade em condições críticas.','Escovas velhas, visão pior.','facil','mecanica'),
('A folga excessiva na direção:','É normal','Indica desgaste e deve ser verificada com urgência','Melhora o conforto','Ajuda em curvas','B','A folga compromete a precisão da trajetória e a segurança.','Volante com folga: oficina imediata.','medio','mecanica'),
('A categoria A da carta de condução destina-se a:','Automóveis ligeiros','Motociclos','Camiões','Autocarros','B','A categoria A habilita à condução de motociclos, com subcategorias conforme a cilindrada e potência.','A de mota.','facil','categorias-carta'),
('Um condutor recém-habilitado deve:','Conduzir sempre a alta velocidade','Adotar prudência acrescida devido à falta de experiência','Ignorar os limites','Conduzir só à noite','B','A inexperiência aumenta o risco, sobretudo nos primeiros anos de condução.','Nos primeiros anos, prudência dobrada.','facil','categorias-carta'),
('Os documentos que devem acompanhar o condutor incluem:','Apenas a carta','Carta de condução e documentos do veículo, incluindo seguro válido','Somente o seguro','Nenhum, se for percurso curto','B','A fiscalização pode exigir a apresentação de todos os documentos legalmente obrigatórios.','Carta, livrete e seguro em dia.','facil','categorias-carta'),
('Emprestar o veículo a quem não tem carta:','É permitido em emergências','Responsabiliza também o proprietário','Não tem consequências','É permitido em vias privadas apenas','B','Quem entrega o veículo a condutor não habilitado incorre em responsabilidade.','Não entregue o carro a quem não pode conduzir.','medio','contraordenacoes'),
('Ultrapassar numa linha contínua:','É tolerado','Constitui infração e cria risco elevado de colisão frontal','É permitido de dia','É permitido se o outro for lento','B','A linha contínua marca zonas sem visibilidade ou espaço suficiente.','Contínua não se pisa.','facil','contraordenacoes'),
('Não parar quando ordenado por agente de autoridade:','É uma contraordenação leve','É uma infração muito grave','É permitido se houver pressa','Depende do horário','B','A desobediência a ordem de paragem é gravemente sancionada.','Ordem de paragem cumpre-se sempre.','medio','contraordenacoes'),
('Circular com matrícula ilegível:','Não tem consequências','É infração por impedir a identificação do veículo','É permitido se estiver suja','Só é problema em autoestrada','B','A matrícula deve estar sempre visível e legível.','Matrícula limpa e visível.','facil','contraordenacoes'),
('Ao aproximar-se de uma passadeira em zona urbana movimentada, deve:','Manter a velocidade se o semáforo estiver verde','Reduzir e verificar se algum peão pretende atravessar','Buzinar','Circular pela esquerda','B','Mesmo com verde, peões podem iniciar a travessia de forma inesperada.','Passadeira exige pé pronto a travar.','facil','zonas-urbanas'),
('A presença de motociclos e motorizadas em cidade exige:','Menos atenção','Verificação frequente dos espelhos e ângulos mortos','Buzinar frequentemente','Circular ao centro','B','Os motociclos são pequenos, rápidos e facilmente escondidos no ângulo morto.','Antes de mudar de fila, procure a mota.','medio','zonas-urbanas'),
('Em vias urbanas com estacionamento em ambos os lados, o condutor deve:','Circular junto aos carros estacionados','Manter distância lateral prevendo portas a abrir e peões','Acelerar','Circular sobre a linha central','B','A distância lateral evita colisões com portas e atropelamentos de quem surge entre carros.','Afaste-se dos carros estacionados.','medio','zonas-urbanas'),
('Ao circular numa estrada com curvas sucessivas fora da localidade:','Deve ultrapassar em cada reta curta','Deve adaptar a velocidade e ultrapassar apenas com visibilidade total','Deve circular ao centro','Deve usar máximos permanentes','B','Retas curtas entre curvas não oferecem espaço suficiente para ultrapassagens seguras.','Curvas seguidas: fique atrás.','medio','fora-localidades'),
('Ao encontrar máquinas agrícolas lentas em estrada nacional:','Deve buzinar até passarem','Deve manter distância e ultrapassar só com visibilidade e espaço','Deve ultrapassar pela berma','Deve colar-se ao veículo','B','As máquinas agrícolas são largas e podem ter cargas salientes.','Trator lento: paciência e visibilidade.','facil','fora-localidades'),
('Sinalização de fim de autoestrada indica que:','Os limites se mantêm','Passam a aplicar-se as regras e limites da via seguinte','A via termina imediatamente','Pode inverter a marcha','B','O condutor deve adaptar a velocidade e o comportamento às novas condições.','Fim da autoestrada: abrande já.','medio','autoestradas'),
('Circular em autoestrada com velocidade muito inferior ao trânsito:','É seguro','Pode criar perigo e obrigar a manobras evasivas','É recomendado','É obrigatório para novos condutores','B','Grandes diferenças de velocidade aumentam o risco de colisão traseira.','Se não acompanha, use outra via.','medio','autoestradas'),
('As áreas de serviço em autoestrada servem para:','Inverter o sentido','Descansar, abastecer e fazer pausas de segurança','Estacionamento de longa duração','Realizar reparações mecânicas complexas','B','As pausas em áreas de serviço são fundamentais no combate à fadiga.','Pare para descansar, não na berma.','facil','autoestradas'),
('Ao sair da autoestrada, o condutor deve:','Travar na faixa de rodagem','Utilizar a via de abrandamento para reduzir a velocidade','Reduzir 500 metros antes','Sair pela berma','B','A redução deve ocorrer na via de desaceleração para não perturbar o trânsito.','Trave na via de saída, não na autoestrada.','medio','autoestradas')
) AS v(qt,a,b,c,d,ca,ex,tp,df,slug)
JOIN public.categories c ON c.slug = v.slug;